"id": "0cac0023-c713-582f-9e83-048adf2eaf71"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "朱珍", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的朱珍，在此段中为击退者。", "biography": null, "status": "draft", "id": "863c86d4-bcc1-57f7-a877-4c9d05eed8ca"}, {"name": "葛从周", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的葛从周，在此段中为降朱全忠者。", "biography": null, "status": "draft", "id": "26557449-8ad3-53a2-9cda-77849bf316c9"}, {"name": "时溥", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的时溥：求援者。", "biography": null, "status": "draft", "id": "075f8bab-c2fc-5a9e-b8b2-a0d12c7ac981"}, {"name": "张延范", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：张延范。", "biography": null, "status": "draft", "id": "6e86081b-ff5d-5258-a8a0-f846aae2ce26"}, {"name": "李璠", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：李璠。", "biography": null, "status": "draft", "id": "0a7791be-f6ce-5a5b-a2d4-60c2d575d602"}, {"name": "钱镠", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为发令者。", "biography": null, "status": "draft", "id": "d61d1f96-7af5-5367-8be8-7a25ee7c85ae"}, {"name": "薛朗", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启三年条所见人物：薛朗。", "biography": null, "status": "draft", "id": "40150662-123e-5c52-a83c-fe5051e0f432"}, {"name": "周宝", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：周宝。", "biography": null, "status": "draft", "id": "1e6765bf-c951-5