INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "孙儒杀秦彦毕师铎郑汉章", "start_year": 888, "end_year": 888, "time_original": "888年正月甲寅", "dynasty": "唐", "description": "孙儒因唐宏诬告秦彦等暗召汴军而杀秦彦、毕师铎、郑汉章，任唐宏为马军使。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a2dad5dc-03e6-5af9-a35a-23d8309724aa"}, {"title": "杨行密杀张守一", "start_year": 888, "end_year": 888, "time_original": "888年正月；具体日未载", "dynasty": "唐", "description": "张守一此前与吕用之一同归杨行密，此后为诸将炼仙丹，并欲干预军府政务；杨行密怒而将其杀死。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "66c198e6-5611-5213-ad88-4b4899451a53"}, {"title": "朱全忠遣军擒石璠", "start_year": 888, "end_year": 888, "time_original": "888年正月；癸亥前", "dynasty": "唐", "description": "石璠率蔡军侵陈、亳，朱全忠遣朱珍、葛从周率骑军迎击并俘石璠。", "phases": [], "location_name": "陈州、亳州方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b1ec6684-e509-5ed6-8856-0f64ba5ecb04"}, {"title": "朝廷任朱全忠蔡州四面行营都统", "start_year": 888, "end_year": 888, "time_original": "888年正月癸亥", "dynasty": "唐", "description": "朝廷任朱全忠为蔡州四面行营都统，代替时溥，诸镇军归其节度。", "phases": [], "location_name": "蔡州方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f144767d-c27e-58fe-a32f-0c2c055d337d"}, {"title": "张廷范赴广陵后密报朱全忠", "start_year": 888, "end_year": 888, "time_original": "888年正月甲子前", "dynasty": "唐", "description": "张廷范到广陵受杨行密礼遇；杨行密听说李璠将来任留后后不悦。张廷范密报朱全忠，建议亲率大军赴镇。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c28ff4d5-71d8-567d-a038-969263fb7700"}, {"title": "朱全忠停止赴淮南", "start_year": 888, "end_year": 888, "time_original": "888年正月甲子", "dynasty": "唐", "description": "朱全忠行至宋州，张廷范从广陵返称杨行密难图；甲子李璠也报告徐军阻道，朱全忠遂停止赴镇。", "phases": [], "location_name": "宋州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "640dfc01-95c2-5ffc-a669-619712c8bbd8"}, {"title": "钱镠杀薛朗祭周宝", "start_year": 888, "end_year": 888, "time_original": "888年正月丙寅", "dynasty": "唐", "description": "钱镠斩薛朗，以其心祭周宝。", "phases": [], "location_name": "杭州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7e94fcb6-942b-5709-8f0f-f5293cfe39a0"}, {"title": "钱镠任阮结润州制置使", "start_year": 888, "end_year": 888, "time_original": "888年正月丙寅", "dynasty": "唐", "description": "钱镠任阮结为润州制置使。", "phases": [], "location_name": "润州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4f6f98f9-e654-5ddb-bec6-31994a452e3c"}, {"title": "朱全忠奏杨行密为淮南留后", "start_year": 888, "end_year": 888, "time_original": "888年二月；具体日未载", "dynasty": "唐", "description": "朱全忠向朝廷奏请任杨行密为淮南留后。", "phases": [], "location_name": "淮南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d3eb7b9e-8cd6-5ff1-aba9-b5f550b73462"}, {"title": "僖宗病中自凤翔返长安", "start_year": 888, "end_year": 888, "time_original": "888年二月乙亥至己丑", "dynasty": "唐", "description": "皇帝乙亥身体不适，壬午离凤翔，己丑抵长安。", "phases": [], "location_name": "凤翔、长安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2963a205-c5c3-5467-b24f-8f0f2f2f05b9"}, {"title": "僖宗赦天下并改元", "start_year": 888, "end_year": 888, "time_original": "888年二月庚寅", "dynasty": "唐", "description": "皇帝赦天下并改元，任韦昭度兼中书令。", "phases": [], "location_name": "长安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "25ce0857-4596-52a7-b787-7e9c8dad47c3"}, {"title": "乐彦祯征民筑魏博罗城", "start_year": null, "end_year": null, "time_original": "888年前；具体年日未载", "dynasty": "唐", "description": "《通鉴》追叙乐彦祯令六州民众筑罗城，百姓苦于劳役；其子乐从训聚私兵，牙兵因而疑惧。", "phases": [], "location_name": "魏博", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1139cebf-dceb-5ab2-a2fb-09bda741178c"}, {"title": "乐彦祯避位居寺，魏军推留后", "start_year": 888, "end_year": 888, "time_original": "乐从训私兵引发猜疑后；具体年日未载", "dynasty": "唐", "description": "乐彦祯因牙兵猜疑而请避位，至龙兴寺为僧；军中推都将代理留后。", "phases": [], "location_name": "魏州龙兴寺", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "cfbdda31-738c-5d1c-b632-02d961da0c8f"}, {"title": "魏博军杀代理留后改推罗弘信", "start_year": 888, "end_year": 888, "time_original": "乐彦祯避位后；具体日未载", "dynasty": "唐", "description": "乐从训率军逼魏州，代理留后未出战，被军众杀害；牙兵另推罗弘信代理留后。", "phases": [], "location_name": "魏州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5c3d59fa-23f4-5bd5-b952-0d60f47e01ce"}, {"title": "罗弘信败乐从训并围内黄", "start_year": 888, "end_year": 888, "time_original": "罗弘信受推后；具体日未载", "dynasty": "唐", "description": "罗弘信率军击败乐从训；乐从训退守内黄，魏军围城。", "phases": [], "location_name": "魏州、内黄", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "479ddce6-6e15-577b-a0c0-94c6fd882dde"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

